// Une entrée dans l’application : même interface de démonstration, données privées séparées.
let integratedAppTab='accueil';
function applicationJump(tab){if(!['accueil','fil','logement','espaces','decisions','activites'].includes(tab))return;integratedAppTab=tab;if(location.hash!=='#application'){location.hash='#application';return}const frame=$('#domaine-application');if(frame){if(frame.dataset.ready==='true')frame.contentWindow.postMessage({type:'domaine:module',tab},location.origin);else frame.src='/cercle-demo/?integre=1&onglet='+tab;}document.querySelectorAll('[data-app-module]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.appModule===tab))}
views.application=function(){return `<section class="integrated-app-head"><div><div class="eyebrow">HABITER · PARTAGER · ORGANISER</div><h1>L’application du Domaine.</h1><p>Votre logement et le Cercle dans une même interface. Explorez le fonctionnement avec un profil fictif, sans compte.</p></div><a class="btn light" href="/cercle-demo/">Mon application ↗</a></section><div class="integrated-app-toolbar"><div role="group" aria-label="Accéder à un module de l’application">${[['accueil','⌂ Accueil'],['fil','◎ Le Cercle'],['logement','▣ Mon logement'],['espaces','❀ Terrasse & travail'],['decisions','◈ Décisions'],['activites','▤ Activités']].map(([id,label])=>`<button data-app-module="${id}" aria-pressed="${integratedAppTab===id}" onclick="applicationJump('${id}')">${label}</button>`).join('')}</div><a id="app-fullscreen-link" href="/cercle-demo/?onglet=${integratedAppTab}" class="textlink" target="_top">Ouvrir en plein écran ↗</a></div><div class="integrated-app-frame"><iframe id="domaine-application" title="Application du Domaine : accueil, réseau social et gestion du logement en démonstration" src="/cercle-demo/?integre=1&onglet=${integratedAppTab}"></iframe></div><p class="smallnote">Démonstration interactive : profils et mesures fictifs, essais effacés en quittant ou rechargeant la démonstration. Les interfaces riveraines présentées utilisent uniquement des données fictives. Les équipements physiques ne sont pas connectés.</p>`};
window.addEventListener('message',event=>{const frame=$('#domaine-application');if(!frame||event.origin!==location.origin||event.source!==frame.contentWindow||event.data?.type!=='domaine:module-active'||!['accueil','fil','logement','espaces','decisions','activites'].includes(event.data.tab))return;integratedAppTab=event.data.tab;frame.dataset.ready='true';document.querySelectorAll('[data-app-module]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.appModule===integratedAppTab));const full=$('#app-fullscreen-link');if(full)full.href='/cercle-demo/?onglet='+integratedAppTab});
views.habitat=function(){integratedAppTab='logement';return views.application()};const housingRoute=routes.find(r=>r[0]==='habitat');if(housingRoute)housingRoute[2]='Gestion du logement';
routes.splice(1,0,['application','◎','L’application du Domaine']);
const homeBeforeApplication=views.accueil;views.accueil=function(){let html=homeBeforeApplication();const intro=`<section class="home-app-intro"><div><div class="eyebrow">UN SEUL LIEU POUR LE QUOTIDIEN</div><h2>Une maison à soi.<br>Une application pour faire le lien.</h2><p>Gérer son logement, retrouver ses voisins, prendre part aux décisions et réserver une table à La Serre. Découvrez les usages concrets de l’application.</p><div><button class="btn" onclick="applicationJump('accueil')">Explorer l’application ↗</button><button class="textlink" onclick="applicationJump('logement')">Voir la gestion du logement →</button></div></div><div class="home-app-preview"><span>DOMAINE · L’APPLICATION</span><div class="home-app-preview-photo"><img src="assets/maison-l-bois-reference.webp" loading="lazy" alt="Illustration du logement dans l’application"><b>Ma maison en L<small>Mon dossier privé</small></b></div><div class="home-app-mini-grid"><button onclick="applicationJump('fil')"><span>◎</span><b>Le Cercle</b><small>Fil & profils</small></button><button onclick="applicationJump('logement')"><span>▣</span><b>Mon logement</b><small>Suivi & entretien</small></button><button onclick="applicationJump('espaces')"><span>❀</span><b>La Serre</b><small>Tables & rencontres</small></button></div></div></section>`;return html.replace('<section class="projection-life">',intro+'<section class="projection-life">')};
const circleBeforeApplication=views.communaute;views.communaute=function(){return circleBeforeApplication().replaceAll('href="/cercle-demo"','href="#application" onclick="integratedAppTab=\'fil\'"')};
const gateBeforeApplication=views.riverains;views.riverains=views.resident=function(){return gateBeforeApplication().replaceAll('href="/cercle-demo"','href="#application"')};
const renderBeforeApplication=render;render=function(){renderBeforeApplication();const nav=$('#nav');nav.querySelectorAll('a[href="#application"]').forEach(a=>a.remove());const a=document.createElement('a');a.href='#application';a.innerHTML='<span class="navicon">◎</span>L’application';if(location.hash==='#application'){a.className='active';a.setAttribute('aria-current','page')}const home=nav.querySelector('a[href="#accueil"]');if(home)home.after(a);else nav.prepend(a);const third=$('#touch-nav')?.querySelectorAll('a')[2];if(third){third.href='#application';third.innerHTML='<span>◎</span><b>L’application</b>';third.removeAttribute('aria-current');if(location.hash==='#application')third.setAttribute('aria-current','page')}};
const appSlide=slides.find(s=>s.title.includes('Tout ce qui fait'));if(appSlide){appSlide.title='Le logement, le collectif.<br>Une seule application.';appSlide.text='Un accueil commun relie le Cercle, la gestion du logement, les décisions, les activités et les réservations des espaces partagés.';appSlide.cards=[['Mon logement','Dossier, relevés manuels, équipements, tâches, interventions et documents privés.'],['Le Cercle','Fil visuel, profils, commentaires, favoris et échanges entre riverains autorisés.'],['La vie commune','Décisions, activités et tables de travail : organiser ensemble les usages du Domaine.']]}
slides.splice(2,0,{k:'LE QUOTIDIEN EN PRATIQUE',title:'Une application à essayer.<br>Un habitat à comprendre.',text:'La démonstration permet de se projeter sans compte. Les données réelles des riverains restent dans leur espace privé.',cards:[['Découvrir','Voir l’habitat en photo, en plan et en 3D, puis explorer l’application.'],['Gérer','Noter un relevé, prévoir un entretien et suivre une demande concernant son logement.'],['Partager','Publier dans le Cercle, proposer une activité ou réserver une table à La Serre.']]});slides.forEach((s,i)=>s.k=String(i+1).padStart(2,'0')+' · '+s.k.replace(/^(?:[0-9]+ · )+/,''));
const slideBeforeApplication=renderSlide;renderSlide=function(){slideBeforeApplication();if(slides[slideIndex].k.includes('LE QUOTIDIEN EN PRATIQUE'))$('#slide .over').insertAdjacentHTML('beforeend','<button class="btn" onclick="document.getElementById(\'deck\').close();applicationJump(\'accueil\')">Essayer l’application intégrée ↗</button>')};
render();
